#include "metaObjectMetadata.h"

/* PNG */
static const wxString s_metadata_64_png = wxT("");

wxIcon ibValueMetaObjectConfiguration::GetIcon() const
{
	return GetIconGroup();
}

wxIcon ibValueMetaObjectConfiguration::GetIconGroup()
{
	static wxIcon icon =
		ibBackendPicture::GetIconFromBase64(s_metadata_64_png, wxSize(16, 16));

	return icon;
}